-- 营销动作库（Phase 0）：扩展 marketing_templates 结构 + 手册动作种子（2026-08-07）
-- 动作库是「选型引擎」的数据底座：按动作阶段/人群类型/渠道/成本档/KPI/红线检索，
-- LLM 只负责在选定模板约束内细化，不再自由发挥。

ALTER TABLE marketing_templates
  ADD COLUMN IF NOT EXISTS action_stage VARCHAR(20),
  ADD COLUMN IF NOT EXISTS audience_type VARCHAR(20) DEFAULT 'scenario',
  ADD COLUMN IF NOT EXISTS cost_tier VARCHAR(20),
  ADD COLUMN IF NOT EXISTS kpi_metric VARCHAR(40),
  ADD COLUMN IF NOT EXISTS seasonal_key VARCHAR(40),
  ADD COLUMN IF NOT EXISTS red_lines JSONB DEFAULT '[]'::jsonb;

INSERT INTO marketing_templates (
  name, category, description, actions, expected_roi, budget_range, duration_days,
  success_rate, channel, target_audience, payload_template, tenant_id,
  action_stage, audience_type, cost_tier, kpi_metric, seasonal_key, red_lines
)
SELECT v.name, v.category, v.description, v.actions::jsonb, v.roi, v.budget, v.days,
       0, v.channel, v.audience,
       jsonb_build_object(
         'audience_type', v.audience_type,
         'cost_tier', v.cost_tier,
         'kpi_metric', v.kpi_metric,
         'seasonal_key', v.seasonal_key,
         'red_lines', v.red_lines::jsonb,
         'execution_steps', v.steps::jsonb
       ), 'default',
       v.category, v.audience_type, v.cost_tier, v.kpi_metric, v.seasonal_key, v.red_lines::jsonb
FROM (VALUES
  ('新客立减首单','拉新','首单8折或送招牌菜，快速降低首次到店门槛','["设定首单立减/送菜","收银台与团购平台同步上架","记录新客到店"]',2.0,'中',7,'dianping','首次到店新客','scenario','medium','new_visit_rate',NULL,'["禁止无限量亏损拼团","禁止好评返现"]','["第1天设定优惠并培训员工","每日统计新客到店数"]'),
